update tb_daily_mst
set    end_yn ='Y'
where  daily_id = #{dailyId}

update tb_daily_mst
set    area_cd      = #{areaCd}
      ,work_type_cd = #{workTypeCd}
      ,upd_id       = #{userId}
      ,upd_dt       = getDate()
where  daily_id     = #{dailyId}

mapper.select:
SELECT a.daily_id AS dailyId ,a.daily_date AS dailyDate
/* 입고량 총액 - 원료 입고금액 */ ,ISNULL(b.raw_receipt_amt, 0) AS inQty
/* 부자재 총액 - 부자재 사용금액 */ ,ISNULL(b.sub_usage_amt, 0) AS outQty
/* 완제품 총액 - 완제품 생산금액 */ ,ISNULL(b.product_prod_amt, 0) + ISNULL(b.product_outsource_prod_amt, 0) AS prodAmt
/* 인건비 총액 - 상세 인건비 금액 합산 */ ,( ISNULL(b.mgmt_day_female_cnt, 0) * ISNULL(b.mgmt_day_work_hour, 0) * ISNULL(b.mgmt_day_hourly_cost, 0)
+ ISNULL(b.regular_day_male_cnt, 0) * ISNULL(b.regular_day_work_hour, 0) * ISNULL(b.regular_day_hourly_cost, 0)
+ ISNULL(b.regular_day_female_cnt, 0) * ISNULL(b.regular_day_work_hour, 0) * ISNULL(b.regular_day_hourly_cost, 0) ) AS laborAmt
/* 총비용 - 원료 + 부자재 + 인건비 + 경비 */ ,( ISNULL(b.raw_usage_amt, 0) + ISNULL(b.sub_usage_amt, 0) + ISNULL(b.indirect_labor_cost, 0) + ISNULL(b.supplies_direct_cost, 0) + ISNULL(b.meal_direct_cost, 0) + ISNULL(b.etc_direct_cost, 0) + ISNULL(b.admin_etc_indirect_cost, 0) + ISNULL(b.depreciation_indirect_cost, 0) + ISNULL(b.finance_indirect_cost, 0) ) AS totalAmt ,a.reg_id AS regId ,a.end_yn AS endYn FROM tb_daily_mst a LEFT JOIN tb_daily_mgmt b ON a.daily_id = b.daily_id WHERE a.daily_date between #{strDate} and #{endDate} and a.type_cd = 'M' ORDER BY a.daily_date DESC, a.daily_id DESC

